{
  "arguments": [
    {
      "claim": "The senior ABiH officer exercised effective command and control over the units that perpetrated the murders, satisfying the “effective authority and control” element of superior responsibility under Article 7(3) ICTY Statute.",
      "reasoning": "The officer, as Chief of the Main Staff and leader of an Inspection Team with coordinating and monitoring functions over the 4th and 6th Corps, was empowered to issue orders consistent with his authority and to consult the Commander on drastic proposals. This functional authority placed him in a position to direct or influence the deployment of the 9th Motorised Brigade, which carried out the killings. Under Rome Statute art.28(a) a person who is “effectively acting as a military commander” and has “effective command and control” is liable, and customary rule.152 confirms that commanders are responsible for crimes committed pursuant to their orders.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "28(a)",
          "quoted_text": "A military commander or person effectively acting as a military commander shall be criminally responsible for crimes within the jurisdiction of the Court committed by forces under his or her effective command and control, or effective authority and control as the case may be, as a result of his or her failure to exercise control properly over such forces, where: (i) That military commander or person either knew or, owing to the circumstances at the time, should have known that the forces were committing or about to commit such crimes; and (ii) That military commander or person failed to take all necessary and reasonable measures within his or her power to prevent or repress their commission or to submit the matter to the competent authorities for investigation and prosecution."
        },
        {
          "type": "customary",
          "instrument": "customary_ihl",
          "rule_number": 152,
          "quoted_text": "Commanders and other superiors are criminally responsible for war crimes committed pursuant to their orders."
        }
      ]
    },
    {
      "claim": "The officer knew, or had reason to know, that the troops under his effective control were committing murders of civilians in Grabovica.",
      "reasoning": "The officer’s coordinating role, his presence in the operational area, and the billeting of troops with the civilian population created circumstances that should have alerted him to unlawful killings. He learned of the murders on the evening of 9 September, indicating that information was available to him during the commission. Under Rome Statute art.28(b)(i) and customary rule.153, a superior who “knew, or consciously disregarded information which clearly indicated” the commission of crimes is liable.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "28",
          "quoted_text": "A military commander or person effectively acting as a military commander shall be criminally responsible for crimes within the jurisdiction of the Court committed by forces under his or her effective command and control, or effective authority and control as the case may be, as a result of his or her failure to exercise control properly over such forces, where: (i) That military commander or person either knew or, owing to the circumstances at the time, should have known that the forces were committing or about to commit such crimes;"
        },
        {
          "type": "customary",
          "instrument": "customary_ihl",
          "rule_number": 153,
          "quoted_text": "Commanders and other superiors are criminally responsible for war crimes committed by their subordinates if they knew, or had reason to know, that the subordinates were about to commit or were committing such crimes and did not take all necessary and reasonable measures in their power to prevent their commission, or if such crimes had been committed, to punish the persons responsible."
        }
      ]
    },
    {
      "claim": "The officer failed to take all necessary and reasonable measures within his power to prevent the murders or to punish the perpetrators, breaching the duty of command responsibility.",
      "reasoning": "After learning of the killings, the officer only instructed a team member to cooperate with an ongoing investigation, without ordering immediate arrest, disciplinary action, or preventive measures for remaining troops. This passive response falls short of the “all necessary and reasonable measures” standard required by art.28(b)(ii) and by AP I art.86(2), which obliges superiors to take feasible measures to prevent or repress a breach.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "28",
          "quoted_text": "That military commander or person failed to take all necessary and reasonable measures within his or her power to prevent or repress their commission or to submit the matter to the competent authorities for investigation and prosecution."
        },
        {
          "type": "treaty",
          "instrument": "ap_i",
          "article": "86(2)",
          "quoted_text": "The fact that a breach of the Conventions or of this Protocol was committed by a subordinate does not absolve his superiors from penal or disciplinary responsibility, as the case may be, if they knew, or had information which should have enabled them to conclude in the circumstances at the time, that he was committing or was going to commit such a breach and if they did not take all feasible measures within their power to prevent or repress the breach."
        }
      ]
    },
    {
      "claim": "The lack of a formal subordinate relationship between the officer and the axis commander of the 9th Brigade does not preclude liability because superior responsibility is grounded in effective control, not formal hierarchy.",
      "reasoning": "Both the Rome Statute (art.28(a)) and customary rule.152 focus on “effective command and control” rather than on rank or formal subordination. The officer’s inspection‑team mandate gave him the practical authority to coordinate combat activities, satisfying the effective control requirement despite the axis commander not being formally subordinate.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "28(a)",
          "quoted_text": "A military commander or person effectively acting as a military commander shall be criminally responsible for crimes within the jurisdiction of the Court committed by forces under his or her effective command and control, or effective authority and control as the case may be"
        },
        {
          "type": "customary",
          "instrument": "customary_ihl",
          "rule_number": 152,
          "quoted_text": "Commanders and other superiors are criminally responsible for war crimes committed pursuant to their orders."
        }
      ]
    },
    {
      "claim": "The officer’s continued role as Chief of the Main Staff and leader of the Inspection Team after June 1993 retained the functional authority necessary for command responsibility, despite the creation of a new post of Commander of the Main Staff.",
      "reasoning": "The factual record shows that the 30 August 1993 order expressly authorized the officer to issue orders “only in keeping with his authority” and to consult the Commander on drastic proposals, preserving his ability to direct operations. This retained functional authority satisfies the effective control test required for superior liability.",
      "citations": []
    }
  ]
}

